    "id": "rtm-0034",
    "record_type": "technique",
    "title": "Cocción de legumbres (Thermomix)",
    "origin": "Libro Cuida tu salud con Thermomix · Transcripción normalizada · Técnica base con anexos",
    "author": "Vorwerk / Thermomix",
    "type": "Cocción",
    "family": "Técnicas y bases culinarias",
    "servings": "4 personas en anexos",
    "time": "Variable según legumbre",
    "difficulty": "Fácil",
    "status": "Pendiente de hacer",
    "ingredients": [
      "Base: la técnica general no fija una cantidad única de legumbre; las cantidades y tiempos concretos se detallan en los anexos.",
      "Remojo: lavar las legumbres con agua fría y dejar en remojo un mínimo de 8 horas.",
      "Reposición de agua: garbanzos, agua hirviendo; alubias/judías, agua fría.",
      "Anexo A · Alubias: 300 g de alubias blancas; 1.000 g de agua fría para remojo (reservar 250 g); 1.400 g de agua + la necesaria; 1/2 cebolla; 1 zanahoria; 1 puerro; 1-2 ajos; 5 granos de pimienta; 50 g de AOVE; 1 cucharadita de sal; laurel o hierbas.",
      "Anexo B · Garbanzos: 250-400 g de garbanzos; 1 pellizco de sal; 1.000 g de agua caliente para remojo; 1.400 g de agua; 1/2 cebolla; 1 zanahoria; 1 puerro; 1-2 ajos; 5 granos de pimienta; 50 g de AOVE; 1 cucharadita de sal; laurel o hierbas; agua hirviendo adicional."
    ],
    "steps": [
      "Ten en cuenta que el tiempo depende del tipo, tamaño y antigüedad de la legumbre.",
      "Mantén las legumbres bien cubiertas de agua durante toda la cocción.",
      "Añade agua por el bocal cuando sea necesario: hirviendo para garbanzos y fría para alubias.",
      "Al finalizar, comprueba el punto y prolonga unos minutos a la misma temperatura y velocidad si siguen duras.",
      "Anexo A · Alubias: tras el remojo, reserva 250 g del agua; cocina con verduras y especias 40 min · 100 °C · vel. 2; añade unos 300 g de agua fría y cocina 30 min más; comprueba el punto.",
      "Anexo B · Garbanzos: calienta 1.400 g de agua 12 min · 100 °C · vel. 1; coloca garbanzos y verduras en el cestillo; cocina 30 min · 100 °C · vel. 2; añade unos 300 g de agua hirviendo y repite dos ciclos de 30 min; si hace falta, prolonga 15 min."
    ],
