    "title": "Cinta de lomo con sorpresa (Thermomix)",
    "origin": "Thermomixcocina.com · Transcripción normalizada",
    "author": "",
    "type": "Cerdo",
    "family": "Carnes y aves",
    "servings": "No indicadas",
    "time": "55 min de cocción + preparación",
    "difficulty": "Elaborada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "Para el lomo: 1,2 kg aprox. de cinta de lomo fresca; 150 g de ciruelas pasas sin hueso; 100 g de nueces; 100 g de higos secos; 100 g de coñac; sal; pimienta; film transparente; papel de aluminio.",
      "Para la salsa: 50 g de mantequilla; 70 g de aceite; 500 g de cebolla; 250 g de higos secos; coñac de la maceración; 400 g de cava semiseco; 2 pastillas de caldo de carne o sal y pimienta; 200 g de agua."
    ],
    "steps": [
      "Haz agujeros grandes por el contorno y extremos del lomo.",
      "Trocea las ciruelas a velocidad 2; la fuente no especifica tiempo. Divide las nueces en cuatro.",
      "Escurre los higos macerados, reserva el coñac, retira el rabito y córtalos en cuatro.",
      "Rellena los agujeros con ciruela, nuez e higo y presiona bien.",
      "Salpimienta y envuelve firmemente en dos capas de film y una de aluminio; coloca en el Varoma.",
      "Trocea la cebolla 5 s · velocidad 3½ y reserva. Coloca la mariposa.",
      "Añade mantequilla, aceite y cebolla y cocina 15 min · Varoma · velocidad 1.",
      "Incorpora higos, coñac reservado, cava, caldo o sazón y agua.",
      "Coloca el Varoma y programa 40 min · Varoma · velocidad 1.",
      "Abre con precaución; desenvuelve y pincha ligeramente para que los jugos caigan al vaso. Retira Varoma y mariposa.",
      "Comprueba sazón y consistencia; si admite más líquido, añade un poco de agua.",
      "Corta el lomo en rodajas finas."
    ],
