    "id": "rtm-0056",
    "record_type": "recipe",
    "title": "Donuts de Dan Lepard",
    "origin": "Webos Fritos · Receta de Dan Lepard (Short & Sweet) · Página web recuperada desde Evernote · 8 unidades",
    "author": "Dan Lepard",
    "type": "Bollería fermentada",
    "family": "Masas, panes y bollería",
    "servings": "8 unidades",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "100 g de leche templada",
      "5 g levadura seca de panadero —o 15 g de levadura fresca—",
      "250 g de harina de fuerza",
      "1 huevo mediano",
      "25 g de azúcar normal",
      "25 g de mantequilla derretida",
      "1 cucharada de extracto vainilla",
      "1 cucharadita de glicerina —es opcional, lee los consejos—",
      "5 g de sal",
      "Para El Glaseado: 150 g de azúcar glas",
      "Para El Glaseado: Entre 2 y 4 cucharadas de agua o leche",
      "Para El Glaseado: Puedes prorratear los ingredientes a otras cantidades usando"
    ],
    "steps": [
      "Mezcla la leche y la levadura en un cuenco.",
      "Añade 100 g de la harina y mezcla con ayuda de tus manos, o de una rasqueta o una cuchara. Tapa con un plástico transparente y deja reposar 2 horas.",
      "Pon el huevo y el azúcar en un cuenco y bate con unas varillas a velocidad media durante 2 min.",
      "Añade la mantequilla, el extracto de vainilla, la glicerina —opcional— y la sal. Incorpora también el prefermento y mezcla con una cuchara.",
      "Agrega los 150 g restantes de harina y termina de mezclar todo bien.",
      "Amasa durante unos 5 min y forma una bola. Para amasar te puedes ayudar de los ganchos que suelen tener las máquina de varillas. Déjala reposar unas 2 horas en un cuenco previamente aceitado.",
      "Echa un poco de harina en la encimera y pon la masa sobre ella. Estira la masa con un rodillo hasta conseguir un grosor de 1 cm aproximadamente. Es importante que si la masa no se estira bien o encoge, la dejes tapada con un paño durante 10 min antes de volver a intentarlo: la masa estará mas manejable.",
      "Corta piezas con la ayuda de un cortador —o dos aros, uno de unos 7 cm de diámetro y otro más pequeño— bien enharinado. Después de cada corte debes volver a enharinar. Pasa las piezas a una bandeja cubierta con papel de horno, con una separación entre pieza y pieza. Pon también las bolitas centrales en la bandeja, separadas de los donuts.",
      "Deja levar otra hora. Yo tapo las piezas con un plástico transparente untado con unas gotitas de aceite de oliva y puesto por encima suavemente, sin apretar la masa.",
      "Pon a calentar el aceite en un cazo hondo a unos 165 °C/170 °C. Recorta el papel de hornear donde está apoyado cada donut con unas tijeras. Para freírlos tienes que introducirlos con el papel en el aceite para que no pierdan su forma. El papel se suelta solo y lo sacas con unas pinzas enseguida. Fríe los donuts durante 2 o 3 min, por un lado y por otro, hasta que tengan un ligero tono dorado. ¡Ojo! Se pasan de color enseguida a tostado. Sácalos a un colador y de ahí a una rejilla. Recuerda: No marees mucho la pieza. Vigílala y cuando veas que está ligeramente dorada dale la vuelta.",
      "Pon el azúcar en un cuenco no muy grande. Añade el agua o la leche hasta obtener un glaseado del espesor que te guste. Si es muy líquido te costará que se forme esa deliciosa costra que queda. Añade la mezcla y remueve.",
      "Cuando los donuts estén fríos coge cada uno con cuidado y báñalo hasta la mitad. Deja reposar en una rejilla."
    ],
    "presentation": "Deja secar el glaseado sobre una rejilla antes de servir.",
    "tips": "Los donuts pueden congelarse cuando el glaseado esté seco, envueltos individualmente. Para freírlos, el aceite debe permitir que floten y mantenerse alrededor de 160-170 °C.",
    "notes": "",
