    "id": "rtm-0062",
    "record_type": "recipe",
    "title": "Espaguetis con pesto de rúcula",
    "origin": "Gastronomía & Cía · Página web recuperada desde Evernote · No indicadas",
    "author": "",
    "type": "Pasta",
    "family": "Pastas y fideos",
    "servings": "No indicadas",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "400 g de espaguetis",
      "un puñado de rúcula fresca",
      "1 cucharada sopera de piñones",
      "cantidad necesaria de parmesano en lascas",
      "sal",
      "Para El Pesto De Rúcula: 60 g de piñones",
      "Para El Pesto De Rúcula: 60 g de rúcula",
      "Para El Pesto De Rúcula: 1 diente de ajo",
      "Para El Pesto De Rúcula: 40 g de queso parmesano",
      "Para El Pesto De Rúcula: 1-2 cucharada sopera de zumo de limón natural",
      "Para El Pesto De Rúcula: una pizca de sal",
      "Para El Pesto De Rúcula: cantidad necesaria de aceite de oliva virgen extra"
    ],
    "steps": [
      "Empieza preparando el pesto, puedes tostar un poco los piñones para potenciar su sabor, hazlo en una sartén sin engrasar y a temperatura media, moviéndolos para que se hagan de forma homogénea.",
      "A continuación pon los piñones en el vaso de la batidora y añade la rúcula bien limpia y seca. Pela el diente de ajo y añádelo también, y a continuación el queso finamente rallado, el zumo de limón y sal al gusto.",
      "Añade un par de cucharadas de aceite de oliva virgen extra para empezar a triturar, el pesto no debe quedar muy fino. Añade más aceite hasta conseguir la cantidad de pesto necesaria para los cuatro platos.",
      "Pon una olla con abundante agua a calentar. Cuando rompa a hervir añade la sal y a continuación los",
      "espaguetis",
      ". Cuécelos hasta que estén al dente. Escúrrelos y vierte el pesto de rúcula reservando cuatro cucharadas para el emplatado.",
      "Emplatado",
      "Sirve los",
      "espaguetis al pesto",
      "coronándolos con una cucharada más de salsa, unos piñones y unas hojas de rúcula fresca. ¡Buen provecho!",
      "Toni Merino"
    ],
    "presentation": "",
    "tips": "",
    "notes": "",
