    "origin": "El Comidista · EL PAÍS · Página web recuperada desde Evernote · Autor/a: Mikel López Iturriaga · 6 personas",
    "author": "Mikel López Iturriaga",
    "type": "Otras legumbres",
    "family": "Legumbres",
    "servings": "6 personas",
    "time": "No indicado",
