      "Hamburguesas: 1/2 cucharadita de pimentón picante",
      "Hamburguesas: 3 cucharadas de perejil picado",
      "Hamburguesas: Leche",
      "Hamburguesas: Aceite de oliva",
      "Hamburguesas: Sal y pimienta negra recién molida",
      "Salsa De Yogur: 2 yogures",
      "Salsa De Yogur: 1/2 limón",
      "Salsa De Yogur: 1/2 cucharada de tomillo seco",
      "Salsa De Yogur: Sal y pimienta negra recién molida"
