      "A continuación añadimos la nata, la leche, el aceite y la esencia de vainilla y batimos hasta integrar bien todos los ingredientes, 2-3 minutos a vel.3 Incorporamos la harina y la levadura mezclando con una espátula para finalizar.",
      "Engrasamos los huecos de la donutera con aceite y los rellenamos hasta casi el borde con la masa, bien con ayuda de una manga pastelera o unas cucharas.",
