      "Los sacamos y dejamos enfriar.",
      "Mientras preparamos nuestra cobertura de chocolate , fundiendo al baño maría un buen chocolate negro (70% cacao).",
      "Bañamos los donetes en el chocolate, escurriendo el exceso del mismo y dejándolos reposar para que se endurezca."
