    "ingredients": [
      "800 gramos caldo de pescado",
      "400 gramos anillas de calamares",
      "150-200 gramos de chalota",
      "150 -200 gramos cebolla",
      "1 dientes ajo",
      "75 gramos aceite",
      "150 gramos vino blanco",
      "250 gramos tomate  - rallado",
      "pimienta y sal",
      "600 gramos fideuá",
      "Azafrán",
      "15-20 langostinos"
    ],
    "steps": [
      "Pelamos los langostinos.",
      "Hacemos un fumet con las cabezas de las gambas :",
      "calentamos el aceite // 2.añadimos las cabezas, las sofreimos 4-5minutos // 3 añadimos 500 gr agua // 10'varoma vel 1 Ponemos en nuestro vaso de thermomix la chalota, la cebolla, los ajos y el aceite y picamos 8 segundos / velocidad 6 después con la espátula bajamos los trozos pegados en los laterales y sofreímos 12 minutos / Varoma / velocidad cuchara La añadimos las anillas de calamar y programamos 10 minutos / Varoma / giro izquierda / velocidad cuchara echamos ahora a nuestro vaso el vino blanco y programamos sin el cubilete para que se evapore el alcohol 5 minutos / Varoma / giro izquierda / velocidad cuchara PASAMOS A UNA PAELLA y dejamos sofreir (que pierda líquido - 5-10' según cantidad que tenga). en este momento le ponemos el tomate, el perejil, la hoja de laurel y la pimienta dejar sofreir bien!! con paciencia, que el tomate se fría bien. echamos ahora los fideos de fideua y el azafrán y volvemos a programar Removemos que los fideos se impregnen del sofrito y tomen un poco de color. añadimos el Caldo de pescado y el fumet de gambas cocinamos el tiempo indicado de los fideos."
    ],
