    "id": "rtm-0092",
    "record_type": "recipe",
    "title": "Fondo claro de pollo",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Fondo",
    "family": "Técnicas y bases culinarias",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "Lo perfecto es una combinación de huesos y carne, los primeros para dar gelatina y cuerpo al fondo, la segunda para dar sabor. Las piezas óptimas son las",
      "alitas como “hueso” y el muslo y contramuslo para la carne",
      ", ya que es la más sabrosa. Como el pollero me suele regalar carcasas, las añado a las alitas.",
      "De proporción, suelo usar entre un 50 y un 70% del peso del agua en huesos y un 50% en carne picada, pero en Modernist Cuisine llegan al 70% de ambos.",
      "cebolla, zanahoria y puerro",
      "champiñón",
      "Las  proporciones, alrededor del 10% del peso del agua de cebolla, 5% de zanahoria, 5% de puerro y 5% de champiñones. En la práctica, para mis lotes de dos litros, una cebolla, una zanahoria, un puerro, y unos cuantos pies de champiñones.",
      "Ajo",
      "perejil, tomillo y pimienta negra"
    ],
    "steps": [
      "El primer paso es blanquear bien los huesos, por higiene y para eliminar impurezas. Tradicionalmente se hace a la vez que el fondo, pero con la olla rápida es más limpio y conveniente hacerlo por separado.",
      "Ponemos los trozos de alitas y carcasas en una olla, cubrimos hasta varios dedos por encima con agua fría, y a fuego lento llevamos a ebullición suave (unos 85ºC). Vamos espumando los restos coagulados que suben a la superficie ayudados por las corrientes de convección, hasta que ya apenas salen impurezas.",
      "Sacamos los huesos, pasándolos a un colador donde limpiamos bien el exterior con agua fría. Esto hay que hacerlo rápido tras sacarlos del agua caliente ya que las impurezas sobre la superficie coagulan rápido.",
      "Así que mejor ir sacando los huesos poco a poco. Volcamos todos los ingredientes menos los aromáticos en la olla rápida, cerramos, ponemos a fuego alto hasta alcanzar la máxima presión (1 bar, 15 psi o 2 rayitas), bajamos el fuego y mantenemos así una hora y media .",
      "Al acabar, dejamos que la presión baje sola, lo que lleva entre veinte minutos y media hora. Abrimos la olla, echamos los aromáticos, cerramos, y los dejamos media hora infusionando.",
      "Colamos ahora el caldo en dos etapas. La primera, con un colador o chino para separar el líquido de los ingredientes.",
      "La segunda, un filtrado muy fino, para el que usamos una estameña, gasa en varias capas, filtro de café, o la fantástica —aunque cara— superbag de 100 micras . Los ingredientes se tiran, con la extracción de sabor que hemos hecho ya no sirven para nada.",
      "Conviene enfriar el caldo lo antes posible. Lo volcamos en uno o, mejor, varios recipientes, de metal si puede ser para transmitir bien el frío, que introducimos en un contenedor más grande lleno de agua fría con hielo.",
      "Cuando mayor sea el contenedor, mejor. Una buena opción es direct amente el fregadero.",
      "Removemos con frecuencia tanto el fondo como el agua. Finalmente, desgrasamos el caldo.",
      "Si tenemos prisa, una jarra desgrasadora es nuestra mejor amiga. Si no, unas horas en el frigorífico llevarán la grasa —por diferencia de densidades— a la superficie, donde el frío la solidificará y será fácil de eliminar con una cuchara o espátula.",
      "En frío el fondo queda como una gelatina, casi se puede cortar con cuchillo."
    ],
    "presentation": "Servir según se indica en la fuente; si no se especifica, presentación no indicada.",
    "tips": "Se conservan los tiempos, temperaturas, reposos y advertencias incluidos en la preparación original. Conservación no especificada; pendiente de confirmar.",
    "notes": "",
    "tags": [
      "Técnicasybasesculinarias",
      "Fondo",
      "Evernote",
      "PendienteDeHacer"
    ],
