    "ingredients": [
      "100 gr. de azúcar moreno",
      "85 gr. de azúcar glas",
      "100 gr. de mantequilla",
      "1 huevo",
      "225 gr. de harina",
      "1/2 sobre de levadura",
      "100 gr. de pepitas de chocolate"
    ],
    "steps": [
      "Si no tenemos azúcar glas, la hacemos poniendo el azúcar blanca en el vaso y pulverizándola durante 15 segundos, a velocidad progresiva 5-7-",
      "",
      "Reservamos.",
      "Echamos la mantequilla en el vaso y programamos 4 minutos, a temperatura 100º y velocidad",
      "",
      "Reservamos en un bol.",
      "Ponemos la mariposa en las cuchillas y echamos el azúcar moreno, el azúcar glas y el huevo.",
      "Batimos durante 40 segundos, a velocidad",
      "",
      "Retiramos la mariposa.",
      "Añadimos la harina, la mantequilla reservada y la levadura.",
      "Mezclamos a velocidad 2, sin tiempo , hasta que se forme una masa homogénea..",
      "Añadimos las pepitas de chocolate y mezclamos con la espátula y si no podemos, lo hacemos con las manos.",
      "Envolvemos la masa en papel film transparente y dejamos reposar 30 minutos en el frigorífico.",
      "Una vez haya reposado, precalentamos el horno a 180º, estiramos la masa con un rodillo y con un cortapastas vamos haciendo las galletas.",
      "Colocamos una lámina de silicona o papel vegetal sobre la placa del horno y encima colocamos las galletas.",
      "Horneamos durante 10-12 minutos (el tiempo depende del horno), a 180º .",
      "Al sacarlas del horno estarán blandas, las dejamos enfriar sobre una rejilla y se endurecerán."
    ],
