    "id": "rtm-0100",
    "record_type": "recipe",
    "title": "Garbanzos con almejas (Thermomix)",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Guiso de legumbres",
    "family": "Legumbres",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "500 gr de almejas",
      "300 gr de cebollas cortadas en cuartos",
      "2 dientes de ajo",
      "50 gr de aceite de oliva virgen extra",
      "1 cucharada de pimentón",
      "800 gr de garbanzos cocidos (2 botes de 400gr), lavados y escurridos",
      "600 ml de caldo de pescado o agua con sal",
      "1 hoja de laurel",
      "1 cayena -opcional",
      "Perejil fresco picado"
    ],
    "steps": [
      "Pon en remojo las almejas, unos 30 minutos en un cuenco de agua fría con abundante sal.",
      "Así soltarán la arena.",
      "Pon en el vaso la cebolla en cuartos, los ajos y el aceite de oliva virgen extra y trocea 4 segundos en velocidad",
      "",
      "Sofríe 10 minutos, Varoma o 120ºC, velocidad",
      "Añade el pimentón -no lo viertas en las cuchillas para que se reparta bien- y mezcla 4 segundos en velocidad",
      "",
      "Vierte 50 gr de los garbanzos lavados y escurridos y los 600 ml de caldo de pescado y tritura 40 segundos en velocidad",
      "",
      "Coloca la mariposa en las cuchillas, incorpora la hoja de laurel, la cayena o una pizca de pimentón picante y cuece 10 minutos, 100ºC, velocidad",
      "",
      "Mientras escurre las almejas en el recipiente Varoma, tapa y reserva .",
      "Incorpora los 750 gr de garbanzos restantes, pon el varoma en su posición y cocina 10 minutos, Varoma, giro a la izquierda, velocidad",
      "",
      "Añade las almejas del varoma al vaso, deja reposar unos minutos y vierte todo en una fuente .",
      "Sirve con perejil picado y sirve caliente.",
      "Listo"
    ],
