      "Escurrir, pintar con un poco de aceite y llevar al horno a 200 grados durante unos 20 minutos, hasta que queden doradas.",
      "Retirar y dejar enfriar.",
      "Cortar las zanahorias en rodajas gruesas y ponerlas en un bol -o en un robot de cocina- con los garbanzos, el ajo, el zumo de limón, el tahini, el pimentón, el agua y las semillas de hinojo.",
      "Triturar hasta conseguir una textura fina, añadiendo un poco más de agua si es necesario.",
      "Servir con semillas de sésamo espolvoreado por encima, y crudités y palitos de pan, regañás o pita para acompañar.",
