    "id": "rtm-0109",
    "record_type": "recipe",
    "title": "Hummus de garbanzos y berenjenas",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Hummus",
    "family": "Entrantes y aperitivos",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "400 gramos de garbanzos cocidos",
      "un poco de caldo de cocción o de agua (para conseguir la densidad deseada)",
      "400 gramos de berenjenas asadas (sin piel)",
      "2 c/s de tahini",
      "3 ramitas de cilantro fresco",
      "1 diente de ajo grande",
      "½ limón (su zumo)",
      "c/n de sal",
      "c/n de aceite de oliva virgen extra",
      "c/n de pimentón de la Vera ahumado",
      "c/n de pimienta negra recién molida",
      "c/n de copos de pimentón ahumado picante (opcional)."
    ],
    "steps": [
      "Los garbanzos se tienen que hacer con antelación, o también se puede optar por utilizar garbanzos cocidos en conserva.",
      "La berenjena también se debe asar con antelación, os recomendamos hacerla en el horno entera y sin pelar, a 200º C, hasta que esté bien tierna, el tiempo variará según el tamaño, si es grande puede necesitar una hora o más.",
      "Una vez que se disponga de los garbanzos cocidos y fríos y de la berenjena asada fría y pelada, pon los dos ingredientes en el vaso de la batidora o procesador de alimentos.",
      "Añade menos de medio vaso de caldo de cocción de los garbanzos (o agua), el tahini, las hojas de cilantro limpias, el diente de ajo pelado y troceado y el zumo de limón (cantidad al gusto, nosotros no llegamos a poner todo el jugo de medio limón).",
      "Añade también sal al gusto, dos o tres cucharadas de aceite de oliva virgen extra y pimentón de la Vera ahumado.",
      "A nosotros nos gusta con bastante pimentón cuando hacemos el hummus con berenjena, el toque ahumado (del buen pimentón) le va genial, de ahí el color que tiene este hummus, pero en principio recomendamos poner menos cantidad.",
      "Si después se quiere, se puede poner más cantidad, incluso al servirlo, espolvoreado para dar más color a la presentación.",
      "Para terminar, añade un poco de pimienta negra recién molida y tritura hasta obtener un puré fino y homogéneo.",
      "Acabado y presentación Sirve el hummus de berenjena en un plato hondo o en un bol y añade unos copos de pimentón ahumado y un hilo de aceite de oliva virgen extra.",
      "Acompaña de algo para mojar, pan de cristal, pan naan, palitos de zanahoria, pepino u otro vegetal, crackers … ¡Buen provecho!"
    ],
