    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Langostinos",
    "family": "Pescados y mariscos",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "200 g de langostino fresco",
      "350 g de setas de temporada",
      "1 cebolla",
      "500 ml de caldo de verduras",
      "100 ml de nata líquida",
      "1 cucharada de mantequilla",
      "aceite de oliva",
      "Pimienta negra molida",
      "Sal",
      "Langostinos sobre crema de setas"
    ],
    "steps": [
      "Primero lavamos bien los langostinos, pelamos y reservamos las cáscaras y la cabezas para otro día.",
      "Picamos la cebolla a juliana.",
      "Limpiamos y troceamos las setas de temporada.",
      "En una sartén agregamos la mantequilla y una vez derretida, agregamos la cebolla, blanqueamos por 5 minutos y agregamos 300 g de los 350 g de setas, salpimentamos.",
      "Agregamos el brandy o coñac, prendemos fuego y flambeamos haciendo círculos con la sartén hasta que se apague el fuego y dejamos reducir por 5 minutos.",
      "Vertimos el caldo caliente, removemos con un batidor de varillas y cocemos unos 10 minutos.",
      "Agregamos 75 ml de los 100 ml de la nata.",
      "Removemos.",
      "Trituramos la crema obtenida con la batidora eléctrica, salpimentamos y repartimos en platos hondos.",
      "En una sartén con un chorrito de aceite, a fuego vivo, agregamos los langostinos, los 50 g de setas restantes, salpimentamos y doramos por ambos lados.",
      "Servimos los langostinos pelados sobre la crema de setas, decoramos con las setas restantes reservadas y con unas gotas de nata.",
      "Toni Merino"
    ],
