    "id": "rtm-0117",
    "record_type": "recipe",
    "title": "Lasaña vegetal",
    "origin": "Archivo histórico Evernote · Transcripción normalizada",
    "author": "",
    "type": "Lasaña",
    "family": "Pastas y fideos",
    "servings": "No indicado",
    "time": "No indicado",
    "difficulty": "No indicada",
    "status": "Pendiente de hacer",
    "ingredients": [
      "160 g (8 cucharadas) de Tomate frito estilo casero SOLÍS",
      "250 ml de Leche evaporada IDEAL",
      "6 láminas de lasaña precocida",
      "200 g de calabacín",
      "200 g de berenjena",
      "90 g de pimiento rojo",
      "50 g de pimiento verde",
      "400 g (8 unidades) de mazorcas baby de maíz",
      "250 g de queso fresco tipo quark",
      "100 g de queso rallado",
      "4 cucharadas de aceite",
      "orégano",
      "sal",
      "pimienta",
      "nuez moscada"
    ],
    "steps": [
      "* Rehogar las mazorcas y las verduras cortadas en dados pequeños en un wok con un poco de aceite, hasta que estén ligeramente cocidas pero crujientes, sazonar con sal y pimienta. * Mezclar el queso fresco con la leche evaporada y sazonarlo con sal y pimienta y un poco de nuez moscada. * En una bandeja para el horno, repartir en la base unas cucharadas de salsa de queso, colocar 2 placas de lasaña pasadas por agua, repartir un poco de las verduras, 4 cucharadas de salsa de tomate frito y espolvorearlo con un poco de orégano. * Colocar de nuevo la operación finalizando con otra capa de lasaña.",
      "Cubrirlo con el resto de la salsa de queso fresco.",
      "Espolvorearlo con un poco de queso rallado. * Cocerlo unos 25-30 minutos en el horno precalentado a 180ºC, hasta que esté ligeramente dorado por encima.",
      "EL TRUCO DEL CHEFEn esta receta simplificamos la clásica bechamel, dando otra alternativa más rápida de leche evaporada y queso.",
      "Enviado desde mi iPhone"
    ],
