      "Pasadas esas 2 horas, las escurrimos y las lavamos.",
      "Ponemos en el vaso la cebolla, el ajo y el aceite.",
      "Programamos 4 segundos, velocidad",
      "Con la espátula bajamos los restos que hayan podido quedar en las paredes del vaso.",
      "Programamos ahora 6 minutos, temperatura varoma, velocidad",
      "",
      "Abrimos la tapa y añadimos el pimentón (tenemos que estar atentos para que caiga en la base del vaso y no sobre las cuchillas) y programamos 1 minuto, temperatura varoma, velocidad",
      "Añadimos ahora las lentejas ya lavadas y escurridas, las rodajas de zanahoria, los cubitos de patata, la hoja de laurel, el agua y la sal.",
      "Programamos 30 minutos, 100º, giro a la izquierda, velocidad cuchara.",
      "Servimos inmediatamente."
