      "Añade los huevos, la vainilla, la pizca de sal , la mitad de la mantequilla y mezcla con unas varillas hasta que este la mezcla uniforme.",
      "Ve añadiendo poco a poco la harina y amasa hasta que se integre completamente.",
      "Tapa la masa con un paño y deja que repose como mínimo 1 hora para que leve la masa.",
      "Añade el resto de la mantequilla( debe estar muy blandita) y el azúcar perlado y vuelve a amasar.",
      "Con thermomix Pon la leche en el vaso y programa 1 min., 37º, vel.",
      "Añade la levadura y programa 10 seg., vel.",
      "Ahora tienes que poner los huevos, la vainilla azucarada, la mitad de la mantequilla (100 gr) la pizca de sal y la harina.Mezcla 20 segundos en velocidad 6, después programa 2 minutos, vaso cerrado, velocidad espiga.",
      "Deja que repose la masa en el vaso como mínimo una hora, tapa el vaso con un paño limpio.",
      "Por ultimo programa 2 minutos, vaso cerrado y velocidad espiga añade por el bocal poco a poco el resto de mantequilla y el azúcar perlado.",
      "Saca la masa del vaso y la pones sobre la encimera o sobre un pape de hornear.",
      "Con las manos humedecidas en agua,tienes que hacer bolas de masa de unos 100 g., así evitaras que la masa se te pegue a las manos ya que queda un pelín pegajosa.",
      "Dejar reposar de nuevo unos 30 minutos .",
      "Precalienta la gofrera a temperatura media.",
      "Cuando esté caliente mete las bolas en el centro de cada lado, verás que al cerrar la gofrera la masa se distribuye.",
      "Deja que se hagan durante unos 3 o 4 minutos y listo.",
