      "Ingredientes: Para 6 hamburguesas de salmón: 800 gr de salmón fresco 150 gr de salmón ahumado 80 gr de paté de atún o salmón 2 dientes de ajo picaditos 1 huevo batido Eneldo en cantidad al gusto Sal Pimienta negra 1 par de cucharaditas de salsa de soja o de mostaza 1 cucharada de pan rallado y un poco más para pasar las hamburguesas Otros: 6 Panes de hamburguesa 2 Tomates Lechuga Preparación: Pica a mano en taquitos pequeñitos el salmón fresco y el ahumado como si fuera para un tartar.",
