      ", comparte otros platos y sus armonías, un gusto para todos los amantes de la gastronomía.",
      "Ingredientes",
      "Para el cremoso de carabinero",
      "125 gramos de cabezas de carabinero",
      "8 gramos de curry rojo en pasta",
      "20 gramos de chalota picada",
      "20 gramos de hinojo picado",
      "10 gramos de mantequilla",
      "30 gramos de brandy o vino blanco seco",
      "150 gramos de agua de tomate",
      "150 gramos de caldo de marisco",
      "200 gramos de nata 35% M.G.",
      "1/2 anís estrellado",
      "2 gramos de agar agar por litro de mezcla.",
      "Para el carabinero",
      "1 carabinero por persona",
      "sal",
      "aceite de oliva virgen extra.",
      "Para el almíbar picante",
      "1/2 litro de agua",
      "75 gramos de azúcar",
      "100 gramos de vino blanco",
      "2 guindillas.",
      "Para la espuma picante de manzana y apio",
      "200 gramos de almíbar picante",
      "125 gramos de licuado de manzana",
      "100 gramos de licuado de apio",
      "5 gramos de hojas de gelatina",
      "sal.",
      "Ensalada de alcachofas",
      "1 alcachofa",
      "de aceite de guindilla.",
      "Otros ingredientes",
      "c/n de brotes de rábano",
      "c/n de lechuga de mar",
      "c/n de espagueti de mar",
      "c/n de huevas de salmón.",
      "Elaboración",
      "Para el cremoso de carabinero",
      "En una olla derretir la mantequilla y ablandar la chalota y el hinojo. Retirar, subir el fuego y dorar las cabezas de los carabineros. Añadir el curry rojo, cocinar un minuto y añadir el brandy. Desglasar y añadir la verdura pochada y el agua de tomate. Reducir a la mitad y añadir el caldo de marisco. Cocinar durante 15 minutos. Incorporar la nata,",
      "levantar",
      "el hervor, poner a punto de sal y pimienta, y fuera del fuego añadir el anis estrellado. Tapar e infusionar 10 minutos. Pasar ligeramente la batidora y colar por una superbag. Llevar a fuego otra vez, añadir el agar agar y cuando hierva cocinar 1 minuto. Desespumar y verter sobre los platos de servicio.",
      "Para el carabinero",
      "Cocinar las colas del carabinero pelado envasado al vacío durante 3 minutos a 55º C junto con una pizca de sal y un chorrito de aceite de oliva. Cortar la cocción en agua con hielo y cortar en medallones.",
      "Para el almíbar picante",
      "Llevar a ebullición el agua y el azúcar. Retirar del fuego y añadir el vino blanco y las guindillas. Infusionar hasta que enfríe. Colar",
      "Para la espuma picante de manzana y apio",
      "Disolver la gelatina previamente hidratada en el almíbar caliente. Añadir los licuados, mezclar e introducir en el sifón con una carga de gas.",
      "Ensalada de alcachofas",
      "Cocer la alcachofa cortada en octavos durante 3 minutos. Cortar la cocción con agua fría, secar y aliñar con sal y aceite de guindillas.",
      "Acabado y presentación",
      "Atemperar el",
      "carabinero",
      "durante 15 segundos en el microondas. Una vez cuajado el cremoso, poner encima el carabinero, la alcachofa, unos trocitos de lechuga de mar y espagueti de mar, las huevas de salmón y los brotes. Poner unos puntos de espuma picante de manzana y apio.",
      "Alejandro Rubio",
      "@Vinosandfood",
      "Abreviaturas",
      "c/s = Cuchara sopera",
      "c/p = Cuchara de postre",
      "c/c = Cuchara de café",
      "c/n = Cantidad necesaria",
      "Toni Merino",
      "Avís legal/Aviso legal"
